#include <stdio.h>
#include <string.h>

typedef struct {
    char name[20];
    int score;
} Student;

Student add_points(Student s, int n) {
    s.score = s.score + n;
    return s;
}

int main(void) {
    Student a;
    strcpy(a.name, "小橘");
    a.score = 60;
    add_points(a, 5);
    printf("%d\n", a.score);
    return 0;
}
